using HelpDeskPro.Api.DTOs; using HelpDeskPro.Api.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using System.Security.Claims;
namespace HelpDeskPro.Api.Controllers; [ApiController][Route("api/auth")]
public class AuthController:ControllerBase { private readonly AuthService auth; public AuthController(AuthService auth){this.auth=auth;} [HttpPost("login")] public async Task<IActionResult> Login(LoginDto dto){var x=await auth.Login(dto.Email,dto.Password); return x==null?Unauthorized(new{message="Invalid email or password"}):Ok(x);} [Authorize][HttpGet("me")] public IActionResult Me()=>Ok(new{Id=User.FindFirstValue(ClaimTypes.NameIdentifier),FullName=User.Identity?.Name,Email=User.FindFirstValue(ClaimTypes.Email),Role=User.FindFirstValue(ClaimTypes.Role)}); }
